// fakeDefaultLovelace is a WSCommander serving the default dashboard. saved is its config, nil
// while it is auto-generated; yaml makes it list as a YAML-mode dashboard.
type fakeDefaultLovelace struct {
	saved   json.RawMessage
	yaml    bool
	calls   []string
	params  map[string]map[string]any
	delErr  error
	saveErr error
}

func (f *fakeDefaultLovelace) Command(_ context.Context, typ string, params map[string]any, result any) error {
	f.calls = append(f.calls, typ)
	if f.params == nil {
		f.params = map[string]map[string]any{}
	}
	f.params[typ] = params
	switch typ {
	case "lovelace/dashboards/list":
		list := []any{}
		if f.yaml {
			list = append(list, map[string]any{"id": "lovelace", "url_path": "lovelace", "mode": "yaml", "title": "Overview"})
		}
		b, _ := json.Marshal(list)
		return json.Unmarshal(b, result)
	case "lovelace/config":
		if f.saved == nil {
			return &client.WSError{Code: "config_not_found", Message: "No config found."}
		}
		return json.Unmarshal(f.saved, result)
	case "lovelace/config/save":
		if f.saveErr != nil {
			return f.saveErr
		}
		f.saved, _ = json.Marshal(params["config"])
		return nil
	case "lovelace/config/delete":
		if f.delErr != nil {
			return f.delErr
		}
		f.saved = nil
		return nil
	}
	return &client.WSError{Code: "unknown_command", Message: typ}
}

// runDefaultDashboardCreate runs the create logic against f. It returns whether it saved, the
// private state it wrote, and its diagnostics.
func runDefaultDashboardCreate(t *testing.T, f *fakeDefaultLovelace) (bool, fakePrivate, diag.Diagnostics) {
	t.Helper()
	r := &defaultDashboardResource{dashboards: client.NewDashboards(f)}
	private := fakePrivate{}
	var diags diag.Diagnostics
	saved := r.create(t.Context(), mustDyn(t, `{"views":[{"title":"Home"}]}`), private, &diags)
	return saved, private, diags
}

// An auto-generated default dashboard is created by saving the config, without a url_path, and
// the stored baseline is recorded (ADR-0023).
func TestDefaultDashboardCreateSavesWithoutURLPath(t *testing.T) {
	f := &fakeDefaultLovelace{}
	saved, private, diags := runDefaultDashboardCreate(t, f)

	checkDiags(t, diags, "")
	if !saved {
		t.Error("create reported that it did not save")
	}
	if _, ok := f.params["lovelace/config/save"]["url_path"]; ok {
		t.Errorf("save params = %v, want no url_path", f.params["lovelace/config/save"])
	}
	if string(f.saved) != `{"views":[{"title":"Home"}]}` {
		t.Errorf("saved = %s", f.saved)
	}
	if _, ok := private[baselineKey]; !ok {
		t.Error("no stored baseline")
	}
}

// Create never replaces a saved config; the user imports it instead.
func TestDefaultDashboardCreateFailsOverExistingConfig(t *testing.T) {
	f := &fakeDefaultLovelace{saved: json.RawMessage(`{"views":[{"title":"Made in the UI"}]}`)}
	saved, _, diags := runDefaultDashboardCreate(t, f)

	if saved {
		t.Error("create reported that it saved")
	}
	checkDiags(t, diags, "tofu import")
	if slices.Contains(f.calls, "lovelace/config/save") {
		t.Errorf("calls = %q, want no save", f.calls)
	}
	if string(f.saved) != `{"views":[{"title":"Made in the UI"}]}` {
		t.Errorf("the saved config was changed to %s", f.saved)
	}
}

func TestDefaultDashboardCreateFailsInYAMLMode(t *testing.T) {
	f := &fakeDefaultLovelace{yaml: true}
	_, _, diags := runDefaultDashboardCreate(t, f)

	checkDiags(t, diags, "yaml mode")
	if slices.Contains(f.calls, "lovelace/config/save") {
		t.Errorf("calls = %q, want no save", f.calls)
	}
}

func readDefaultDashboard(t *testing.T, f *fakeDefaultLovelace, prior defaultDashboardModel) (defaultDashboardModel, resource.ReadResponse) {
	t.Helper()
	r := &defaultDashboardResource{dashboards: client.NewDashboards(f)}
	state := stateOf(t, r, prior)
	resp := resource.ReadResponse{State: state}
	r.Read(t.Context(), resource.ReadRequest{State: state}, &resp)
	var got defaultDashboardModel
	if !resp.Diagnostics.HasError() {
		if diags := resp.State.Get(t.Context(), &got); diags.HasError() {
			t.Fatal(diags)
		}
	}
	return got, resp
}

// An auto-generated default dashboard reads with a null config, so the next apply saves the
// configured one.
func TestDefaultDashboardReadAutoGeneratedLeavesConfigNull(t *testing.T) {
	prior := defaultDashboardModel{ID: types.StringValue(defaultDashboardID), Config: mustDyn(t, `{"views":[]}`)}
	got, resp := readDefaultDashboard(t, &fakeDefaultLovelace{}, prior)

	checkDiags(t, resp.Diagnostics, "")
	if !got.Config.IsNull() {
		t.Errorf("config = %v, want null", got.Config)
	}
}

// After an import, the state holds only the id; Read fills in the config HA stored.
func TestDefaultDashboardReadAfterImportReadsTheConfig(t *testing.T) {
	prior := defaultDashboardModel{ID: types.StringValue(defaultDashboardID), Config: dyntype.NewNull()}
	f := &fakeDefaultLovelace{saved: json.RawMessage(`{"views":[{"title":"Made in the UI"}]}`)}
	got, resp := readDefaultDashboard(t, f, prior)

	checkDiags(t, resp.Diagnostics, "")
	if want := mustDyn(t, `{"views":[{"title":"Made in the UI"}]}`); !got.Config.Equal(want) {
		t.Errorf("config = %v, want %v", got.Config, want)
	}
	if _, ok := f.params["lovelace/config"]["url_path"]; ok {
		t.Errorf("config params = %v, want no url_path", f.params["lovelace/config"])
	}
}

func TestDefaultDashboardReadFailsInYAMLMode(t *testing.T) {
	prior := defaultDashboardModel{ID: types.StringValue(defaultDashboardID), Config: mustDyn(t, `{"views":[]}`)}
	_, resp := readDefaultDashboard(t, &fakeDefaultLovelace{yaml: true}, prior)

	checkDiags(t, resp.Diagnostics, "yaml mode")
}

func TestDefaultDashboardDeleteResetsToAutoGenerated(t *testing.T) {
	f := &fakeDefaultLovelace{saved: json.RawMessage(`{"views":[]}`)}
	r := &defaultDashboardResource{dashboards: client.NewDashboards(f)}
	resp := resource.DeleteResponse{}
	r.Delete(t.Context(), resource.DeleteRequest{}, &resp)

	checkDiags(t, resp.Diagnostics, "")
	if f.saved != nil {
		t.Errorf("saved = %s, want it deleted", f.saved)
	}
	if len(f.params["lovelace/config/delete"]) != 0 {
		t.Errorf("delete params = %v, want none", f.params["lovelace/config/delete"])
	}
}

func TestDefaultDashboardDeleteOfMissingConfigIsFine(t *testing.T) {
	f := &fakeDefaultLovelace{delErr: &client.WSError{Code: "config_not_found", Message: "No config found."}}
	r := &defaultDashboardResource{dashboards: client.NewDashboards(f)}
	resp := resource.DeleteResponse{}
	r.Delete(t.Context(), resource.DeleteRequest{}, &resp)

	checkDiags(t, resp.Diagnostics, "")
}

func TestDefaultDashboardImportAcceptsOnlyTheSingletonID(t *testing.T) {
	r := &defaultDashboardResource{}
	for id, wantErr := range map[string]bool{defaultDashboardID: false, "lovelace": true, "": true} {
		state := stateOf(t, r, defaultDashboardModel{ID: types.StringNull(), Config: dyntype.NewNull()})
		resp := resource.ImportStateResponse{State: state}
		r.ImportState(t.Context(), resource.ImportStateRequest{ID: id}, &resp)
		if got := resp.Diagnostics.HasError(); got != wantErr {
			t.Errorf("import %q: error = %v, want %v", id, got, wantErr)
		}
	}
}
